const defaultData = [
    { name: 'Jan', fullMonth: 'Januari', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Feb', fullMonth: 'Februari', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Mar', fullMonth: 'Maret', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Apr', fullMonth: 'April', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Mei', fullMonth: 'Mei', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Jun', fullMonth: 'Juni', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Jul', fullMonth: 'Juli', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Agu', fullMonth: 'Agustus', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Sep', fullMonth: 'September', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Okt', fullMonth: 'Oktober', Baru: 6, Bekas: 5, Rusak: 3, pctBaru: 50, pctBekas: 34, pctRusak: 16 },
    { name: 'Nov', fullMonth: 'November', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
    { name: 'Des', fullMonth: 'Desember', Baru: 0, Bekas: 0, Rusak: 0, pctBaru: 0, pctBekas: 0, pctRusak: 0 },
];

/* Gaya tiap kartu (class Tailwind ditulis utuh agar terbaca compiler) */
