        light: 'bg-gradient-to-br from-[#e3f3ff] via-white to-[#c4e4ff] border-sky-100 hover:border-sky-300',
        dark: 'bg-gradient-to-br from-sky-950/70 via-slate-900 to-slate-900 border-sky-900/60 hover:border-sky-700',
        badge: 'from-[#38bdf8] via-[#0284c7] to-[#0369a1]',
        badgeShadow: 'shadow-[inset_0_2px_4px_rgba(255,255,255,0.8),inset_0_-4px_8px_rgba(0,0,0,0.35),0_12px_24px_rgba(2,132,199,0.35)]',
        value: 'text-[#0080e5]',
