        badgeShadow: 'shadow-[inset_0_2px_4px_rgba(255,255,255,0.8),inset_0_-4px_8px_rgba(0,0,0,0.35),0_12px_24px_rgba(139,92,246,0.35)]',
        value: 'text-[#7c3aed]',
