const fmtNum = (n, d = 1) => Number(n || 0).toLocaleString('id-ID', { maximumFractionDigits: d });
const sumPct = (r) => (Number(r.pctBaru) || 0) + (Number(r.pctBekas) || 0) + (Number(r.pctRusak) || 0);
const sumUnits = (r) => (Number(r.Baru) || 0) + (Number(r.Bekas) || 0) + (Number(r.Rusak) || 0);

/* ───────────────────────── Bentuk grafik kustom ───────────────────────── */

/* Batang berdiri: ujung atas membulat + kilau tipis */
const PillarBar = ({ x, y, width, height, fill }) => {
    if (!height || height <= 0 || !width) return null;
    const r = Math.min(9, width / 2, height);
    const d = `M${x},${y + height} V${y + r} Q${x},${y} ${x + r},${y} H${x + width - r} Q${x + width},${y} ${x + width},${y + r} V${y + height} Z`;
    return (
        <g>
            <path d={d} fill={fill} />
            {height > r + 8 && width > 10 && (
                <rect x={x + 3} y={y + r} width={3} height={height - r - 6} rx={1.5} fill="#fff" opacity={0.3} />
            )}
        </g>
    );
};

/* Segmen stacked bar: hanya segmen paling atas yang membulat, ada angka di dalam */
const StackSegment = ({ x, y, width, height, fill, isTop, label, isDark }) => {
    if (!height || height <= 0 || !width) return null;
    const r = isTop ? Math.min(10, width / 2, height) : 0;
    const d = isTop
        ? `M${x},${y + height} V${y + r} Q${x},${y} ${x + r},${y} H${x + width - r} Q${x + width},${y} ${x + width},${y + r} V${y + height} Z`
        : `M${x},${y} H${x + width} V${y + height} H${x} Z`;
    return (
        <g>
            <path d={d} fill={fill} stroke={isDark ? '#0f172a' : '#ffffff'} strokeWidth={1.5} />
            {height >= 18 && (
                <text x={x + width / 2} y={y + height / 2 + 4} textAnchor="middle" fontSize={11} fontWeight={800} fill="#fff">
                    {label}
                </text>
            )}
        </g>
    );
};

/* Label angka di atas batang */
const valueLabel = (color, isDark) => (props) => {
    const { x, y, width, value } = props;
    if (!value || Number(value) <= 0) return null;
    return (
        <text
            x={x + width / 2}
            y={y - 7}
            textAnchor="middle"
            fontSize={11}
            fontWeight={800}
            fill={color}
            stroke={isDark ? '#0f172a' : '#ffffff'}
            strokeWidth={3}
            paintOrder="stroke"
        >
            {fmtNum(value)}%
        </text>
    );
};

/* Titik garis: hanya muncul pada bulan yang punya data, lengkap dengan angka */
const makeDot = (k, isDark) => (p) => {
    const { cx, cy, payload, index } = p;
    const id = `dot-${k.key}-${index}`;
    if (cx == null || cy == null || !payload || sumPct(payload) <= 0) return <g key={id} />;
    return (
        <g key={id}>
            <circle cx={cx} cy={cy} r={6} fill={isDark ? '#0f172a' : '#fff'} stroke={k.color} strokeWidth={3} />
            <text
                x={cx}
                y={cy - 13}
                textAnchor="middle"
                fontSize={11}
                fontWeight={800}
                fill={k.color}
                stroke={isDark ? '#0f172a' : '#fff'}
                strokeWidth={3}
                paintOrder="stroke"
            >
                {fmtNum(payload[k.pct])}%
            </text>
        </g>
    );
};

/* ───────────────────────── Komponen utama ───────────────────────── */

/* backgroundImage: otomatis memakai gambar bawaan (BG_KONDISI di bagian paling bawah file).
   Boleh diganti lewat prop jika ingin gambar lain. */
export default function GrafikKondisiBarang({ data = [], backgroundImage = BG_KONDISI }) {
    const [activeKondisi, setActiveKondisi] = useState({ Baru: true, Bekas: true, Rusak: true });
    const [isDarkMode, setIsDarkMode] = useState(false);
    const [chartType, setChartType] = useState('line');

    const isDark = isDarkMode;
    const toggleKondisi = (key) => setActiveKondisi((prev) => ({ ...prev, [key]: !prev[key] }));

    const chartData = data && data.length > 0 ? data : defaultData;
    const activeKeys = KEYS.filter((k) => activeKondisi[k.key]);
    const currentType = chartTypeOptions.find((c) => c.id === chartType) || chartTypeOptions[0];
    const HeaderIcon = currentType.icon;

    /* Bulan puncak: jumlah unit terbanyak (jika tidak ada unit, pakai jumlah persen) */
    const { activeData, noData, hasUnits, monthUnits } = useMemo(() => {
        const withUnits = chartData.some((r) => sumUnits(r) > 0);
        const score = (r) => (withUnits ? sumUnits(r) : sumPct(r));
        const peak = chartData.reduce((best, r) => (score(r) > score(best) ? r : best), chartData[0]);
        return {
            activeData: peak,
            noData: score(peak) <= 0,
            hasUnits: withUnits,
            monthUnits: sumUnits(peak),
        };
    }, [chartData]);

    const dominant = useMemo(() => {
        const best = KEYS.reduce((a, k) => ((Number(activeData[k.pct]) || 0) > (Number(activeData[a.pct]) || 0) ? k : a), KEYS[0]);
        return best;
    }, [activeData]);

    /* Warna tema untuk elemen chart */
    const axisText = isDark ? '#94a3b8' : '#475569';
    const axisLine = isDark ? '#475569' : '#cbd5e1';
    const gridColor = isDark ? '#334155' : '#e2e8f0';

    /* Definisi gradasi (dipakai semua jenis grafik) */
    const defs = (
        <defs>
            <linearGradient id="kb_baru" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#38bdf8" />
                <stop offset="100%" stopColor="#0369a1" />
            </linearGradient>
            <linearGradient id="kb_bekas" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#fcd34d" />
                <stop offset="100%" stopColor="#d97706" />
            </linearGradient>
            <linearGradient id="kb_rusak" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#fb7185" />
                <stop offset="100%" stopColor="#be123c" />
            </linearGradient>
            <linearGradient id="kb_area_baru" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#0090e7" stopOpacity={0.35} />
                <stop offset="100%" stopColor="#0090e7" stopOpacity={0.02} />
            </linearGradient>
            <linearGradient id="kb_area_bekas" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#f59e0b" stopOpacity={0.32} />
                <stop offset="100%" stopColor="#f59e0b" stopOpacity={0.02} />
            </linearGradient>
            <linearGradient id="kb_area_rusak" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#e11d48" stopOpacity={0.3} />
                <stop offset="100%" stopColor="#e11d48" stopOpacity={0.02} />
            </linearGradient>
        </defs>
    );

    const commonProps = { data: chartData, margin: { top: 26, right: 20, left: 0, bottom: 5 } };

    const commonAxis = (
        <>
            {defs}
            <CartesianGrid strokeDasharray="4 4" vertical={false} stroke={gridColor} />
            <XAxis
                dataKey="name"
                interval={0}
                tickLine={false}
                axisLine={{ stroke: axisLine }}
                tick={{ fill: axisText, fontSize: 13, fontWeight: 600 }}
                padding={{ left: 12, right: 12 }}
                dy={8}
            />
            <YAxis
                domain={[0, 100]}
                ticks={[0, 25, 50, 75, 100]}
                tickFormatter={(v) => `${v}%`}
                width={48}
                tickLine={false}
                axisLine={false}
                tick={{ fill: axisText, fontSize: 12, fontWeight: 600 }}
            />
            {!noData && (
                <ReferenceLine x={activeData.name} stroke={isDark ? '#a78bfa' : '#8b5cf6'} strokeDasharray="5 5" strokeOpacity={0.55} />
            )}
            <Tooltip
                cursor={
                    chartType === 'line'
                        ? { stroke: isDark ? '#64748b' : '#94a3b8', strokeWidth: 1, strokeDasharray: '4 4' }
                        : { fill: isDark ? 'rgba(148,163,184,0.08)' : 'rgba(99,102,241,0.07)' }
                }
                content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0].payload;
                    return (
                        <div
                            className={`border rounded-xl p-3 text-sm shadow-xl backdrop-blur-md min-w-[160px] ${
                                isDark ? 'bg-slate-800/95 border-slate-700 text-slate-200' : 'bg-white/95 border-slate-100 text-slate-700'
                            }`}
                        >
                            <div className={`font-bold border-b pb-2 mb-2 text-center ${isDark ? 'border-slate-700 text-slate-100' : 'border-slate-100 text-slate-800'}`}>
                                {d.fullMonth}
                            </div>
                            {KEYS.filter((k) => activeKondisi[k.key]).map((k) => (
                                <div key={k.key} className="flex items-center justify-between gap-4 font-bold my-1" style={{ color: k.color }}>
                                    <span>{k.key}</span>
                                    <span>
                                        {fmtNum(d[k.pct])}%
                                        {d[k.key] !== undefined && (
                                            <span className="ml-1.5 text-[11px] font-semibold opacity-70">({fmtNum(d[k.key], 0)} Unit)</span>
                                        )}
                                    </span>
                                </div>
                            ))}
                        </div>
                    );
                }}
            />
        </>
    );

    const renderChart = () => {
        if (chartType === 'line') {
            return (
                <ComposedChart {...commonProps}>
                    {commonAxis}
                    {activeKeys.map((k) => (
                        <Area
                            key={k.key}
                            type="linear"
                            dataKey={k.pct}
                            stroke={k.color}
                            strokeWidth={3}
                            strokeLinejoin="round"
                            fill={`url(#${k.area})`}
                            dot={makeDot(k, isDark)}
                            activeDot={{ r: 7, fill: k.color, stroke: '#fff', strokeWidth: 2 }}
                            isAnimationActive={false}
                        />
                    ))}
                </ComposedChart>
            );
        }

        if (chartType === 'grouped-bar') {
            return (
                <BarChart {...commonProps} barGap={4} barCategoryGap="14%">
                    {commonAxis}
                    {activeKeys.map((k) => (
                        <Bar
                            key={k.key}
                            dataKey={k.pct}
                            barSize={16}
                            fill={`url(#${k.grad})`}
                            shape={<PillarBar />}
                            background={{ fill: isDark ? 'rgba(148,163,184,0.07)' : 'rgba(148,163,184,0.12)', radius: 8 }}
                            isAnimationActive={false}
                        >
                            <LabelList dataKey={k.pct} content={valueLabel(k.color, isDark)} />
                        </Bar>
                    ))}
                </BarChart>
            );
        }

        if (chartType === 'stacked-bar') {
            return (
                <BarChart {...commonProps} barCategoryGap="22%">
                    {commonAxis}
                    {activeKeys.map((k) => (
                        <Bar
                            key={k.key}
                            dataKey={k.pct}
                            stackId="kondisi"
                            barSize={34}
                            fill={`url(#${k.grad})`}
                            isAnimationActive={false}
                            shape={(p) => {
                                const row = p.payload || {};
                                const topKey = [...activeKeys].reverse().find((a) => (Number(row[a.pct]) || 0) > 0)?.key;
                                return (
                                    <StackSegment
                                        x={p.x}
                                        y={p.y}
                                        width={p.width}
                                        height={p.height}
                                        fill={p.fill}
                                        isTop={topKey === k.key}
                                        isDark={isDark}
                                        label={`${fmtNum(row[k.pct])}%`}
                                    />
                                );
                            }}
                        />
                    ))}
                </BarChart>
            );
        }

        return null;
    };

    /* Kartu persentase (Baru / Bekas / Rusak) */
    const conditionCards = [
        { id: 'Baru', pct: 'pctBaru', label: '% Baru (Segel)', note: 'Barang masih tersegel' },
        { id: 'Bekas', pct: 'pctBekas', label: '% Bekas (Second)', note: 'Barang pernah dipakai' },
        { id: 'Rusak', pct: 'pctRusak', label: '% Rusak', note: 'Perlu perbaikan atau ganti' },
    ];

    return (
        <div
            className={`relative p-6 sm:p-8 rounded-[2.5rem] font-sans w-full max-w-6xl mx-auto overflow-hidden shadow-2xl transition-colors duration-500 border ${
                isDark ? 'bg-slate-950 border-slate-800 shadow-blue-950/30' : 'bg-[#f8f7e6] border-white shadow-blue-900/10'
            }`}
        >
            {/* Gambar latar */}
            <div
                className="absolute inset-0 pointer-events-none"
                style={{
                    backgroundImage: `url(${backgroundImage})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    backgroundRepeat: 'no-repeat',
                }}
            />
            {/* Lapisan gelap untuk mode gelap */}
            <div className={`absolute inset-0 pointer-events-none transition-opacity duration-500 bg-slate-950/80 ${isDark ? 'opacity-100' : 'opacity-0'}`} />

            {/* ── Header ── */}
            <div
                className={`flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6 mb-7 relative z-10 rounded-3xl border p-4 backdrop-blur-md transition-colors duration-300 ${
                    isDark ? 'bg-slate-900/70 border-slate-700/70' : 'bg-white/70 border-white/80 shadow-sm'
                }`}
            >
                <div className="flex items-center gap-4">
                    <div className="shrink-0 w-14 h-14 rounded-[22px] bg-gradient-to-br from-[#38bdf8] via-[#0284c7] to-[#0369a1] flex items-center justify-center shadow-[inset_0_2px_4px_rgba(255,255,255,0.7),inset_0_-4px_8px_rgba(0,0,0,0.3),0_10px_20px_rgba(2,132,199,0.35)] transition-transform duration-300 hover:scale-105">
                        <HeaderIcon className="w-7 h-7 text-white drop-shadow-[0_2px_3px_rgba(0,0,0,0.3)]" />
                    </div>
                    <div>
                        <h3 className={`text-xl sm:text-2xl font-black tracking-tight leading-tight ${isDark ? 'text-white' : 'text-[#1e293b]'}`}>
                            Grafik Tren Persentase Kondisi Barang Bulanan
                        </h3>
                        <p className={`text-sm font-semibold mt-0.5 ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>
                            Tampilan {currentType.label.toLowerCase()}, persentase per bulan
                        </p>
                    </div>
                </div>

                <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto justify-start lg:justify-end">
                    {/* Filter legenda */}
                    <div className={`flex items-center gap-4 px-5 py-2.5 rounded-full shadow-sm border backdrop-blur-md transition-colors duration-300 ${isDark ? 'bg-slate-800/80 border-slate-700' : 'bg-white/75 border-white'}`}>
                        {KEYS.map((item) => (
                            <button
                                key={item.key}
                                type="button"
                                onClick={() => toggleKondisi(item.key)}
                                aria-pressed={activeKondisi[item.key]}
                                className={`flex items-center gap-2 text-xs sm:text-sm transition-all cursor-pointer select-none font-bold ${
                                    activeKondisi[item.key] ? (isDark ? 'text-slate-200' : 'text-slate-700') : 'text-slate-400 line-through opacity-50'
                                }`}
                            >
                                <span className={`w-3 h-3 rounded-full ${activeKondisi[item.key] ? item.dot : 'bg-slate-300'}`} />
                                <span>{item.label}</span>
                            </button>
                        ))}
                    </div>

                    {/* Pilihan jenis grafik */}
                    <div className={`flex items-center p-1 rounded-full border shadow-sm backdrop-blur-md transition-colors duration-300 ${isDark ? 'bg-slate-800/80 border-slate-700' : 'bg-white/80 border-white'}`}>
                        {chartTypeOptions.map((option) => {
                            const IconComponent = option.icon;
                            const isActive = chartType === option.id;
                            return (
                                <button
                                    key={option.id}
                                    type="button"
                                    onClick={() => setChartType(option.id)}
                                    title={`Tampilkan grafik ${option.label}`}
                                    aria-pressed={isActive}
                                    className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold transition-all duration-300 cursor-pointer ${
                                        isActive
                                            ? 'bg-gradient-to-r from-[#0ea5e9] to-[#0284c7] text-white shadow-md shadow-blue-500/30'
                                            : isDark
                                            ? 'text-slate-400 hover:text-slate-200 hover:bg-slate-700/50'
                                            : 'text-slate-600 hover:text-slate-900 hover:bg-slate-100'
                                    }`}
                                >
                                    <IconComponent className="w-4 h-4" />
                                    <span className="hidden sm:inline">{option.label}</span>
                                </button>
                            );
                        })}
                    </div>

                    {/* Mode gelap */}
                    <button
                        type="button"
                        onClick={() => setIsDarkMode((p) => !p)}
                        title={isDark ? 'Beralih ke mode terang' : 'Beralih ke mode gelap'}
                        className={`p-2.5 rounded-full transition-all duration-300 shadow-md border cursor-pointer ${
                            isDark ? 'bg-slate-800 border-slate-700 text-amber-400 hover:bg-slate-700' : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'
                        }`}
                    >
                        {isDark ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
                    </button>
                </div>
            </div>

            {/* ── Kotak grafik ── */}
            <div
                className={`relative z-10 rounded-3xl border shadow-sm p-4 sm:p-6 mb-6 backdrop-blur-sm transition-colors duration-300 ${
                    isDark ? 'bg-slate-900/75 border-slate-800/80' : 'bg-white/65 border-white/80'
                }`}
            >
                <div
                    className={`relative w-full h-[340px] rounded-2xl border overflow-hidden ${isDark ? 'border-slate-700' : 'border-white/70 shadow-inner'}`}
                    style={{
                        backgroundImage: `radial-gradient(circle at 1px 1px, ${isDark ? 'rgba(148,163,184,0.16)' : 'rgba(255,255,255,0.58)'} 1px, transparent 0), linear-gradient(${isDark ? 'rgba(2,6,23,0.72), rgba(15,23,42,0.66)' : 'rgba(255,255,255,0.72), rgba(248,250,252,0.62)'}), url(${backgroundImage})`,
                        backgroundSize: '22px 22px, cover, cover',
                        backgroundPosition: 'center, center, center',
                        backgroundRepeat: 'repeat, no-repeat, no-repeat',
                    }}
                >
                    <ResponsiveContainer width="100%" height="100%">
                        {renderChart()}
                    </ResponsiveContainer>

                    {noData && (
                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                            <span className={`px-4 py-2 rounded-full text-sm font-bold border ${isDark ? 'bg-slate-800 border-slate-700 text-slate-300' : 'bg-white border-slate-200 text-slate-500'}`}>
                                Belum ada data kondisi barang
                            </span>
                        </div>
                    )}
                </div>

                {/* Keterangan grafik + statistik singkat */}
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mt-3">
                    <p className={`text-xs font-medium max-w-2xl ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{currentType.caption}</p>
                    {!noData && (
                        <span className={`shrink-0 inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold ${isDark ? 'bg-violet-900/40 text-violet-300' : 'bg-violet-100 text-violet-700'}`}>
                            <span className="w-2 h-2 rounded-full bg-violet-500" />
                            Puncak: {activeData.fullMonth || activeData.name}
                            {hasUnits && `, ${fmtNum(monthUnits, 0)} Unit`}
                        </span>
                    )}
                </div>
            </div>

            {/* ── 4 kartu ringkasan ── */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6 relative z-10">
                {conditionCards.map((c) => {
                    const s = CARD_STYLES[c.id];
                    const Icon = s.Icon;
                    const pct = Number(activeData[c.pct]) || 0;
                    return (
                        <div
                            key={c.id}
                            className={`relative rounded-[2rem] pt-7 pb-9 px-5 border flex flex-col items-center text-center transition-all duration-300 shadow-sm hover:shadow-xl hover:-translate-y-0.5 overflow-hidden group ${isDark ? s.dark : s.light}`}
                        >
                            <div className={`absolute -right-10 -top-10 w-36 h-36 rounded-full border-[16px] pointer-events-none ${isDark ? s.ringDark : s.ringLight}`} />
                            <Icon className={`absolute -left-7 -bottom-7 w-36 h-36 -rotate-12 pointer-events-none ${isDark ? s.ghostDark : s.ghostLight}`} strokeWidth={1.3} />

                            <div className="relative z-10 flex flex-col items-center w-full">
                                <div className={`w-16 h-16 mb-4 rounded-[24px] bg-gradient-to-br ${s.badge} ${s.badgeShadow} flex items-center justify-center transition-all duration-300 group-hover:scale-110 group-hover:-translate-y-1`}>
                                    <Icon className="w-8 h-8 text-white stroke-[2.2] drop-shadow-[0_2px_4px_rgba(0,0,0,0.35)]" />
                                </div>

                                <div className={`text-4xl font-black tracking-tight ${s.value}`}>{fmtNum(pct)}%</div>
                                <div className={`text-sm font-bold mt-1.5 ${isDark ? 'text-slate-200' : 'text-slate-700'}`}>{c.label}</div>
                                <div className="text-xs font-semibold mt-0.5 text-slate-400">({activeData.name})</div>

                                {/* Bar progres */}
                                <div className={`w-full max-w-[150px] h-2 rounded-full mt-4 overflow-hidden ${isDark ? s.trackDark : s.trackLight}`}>
                                    <div className={`h-full rounded-full bg-gradient-to-r ${s.bar}`} style={{ width: `${Math.min(100, pct)}%` }} />
                                </div>

                                {hasUnits ? (
                                    <span className={`mt-3 inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-bold ${isDark ? s.chipDark : s.chipLight}`}>
                                        <Boxes className="w-3 h-3" />
                                        {fmtNum(activeData[c.id], 0)} Unit
                                    </span>
                                ) : (
                                    <span className="mt-3 text-[11px] font-medium text-slate-400">{c.note}</span>
                                )}
                            </div>

                            <button
                                type="button"
                                aria-label={`Lihat detail ${c.id}`}
                                className={`absolute bottom-0 right-0 w-11 h-11 bg-gradient-to-br ${s.corner} rounded-tl-2xl rounded-br-[2rem] flex items-center justify-center cursor-pointer shadow-[inset_0_2px_3px_rgba(255,255,255,0.6),inset_0_-2px_4px_rgba(0,0,0,0.25)] transition-transform hover:scale-105 active:scale-95`}
                            >
                                <ChevronRight className="w-5 h-5 text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.3)]" />
                            </button>
                        </div>
                    );
                })}

                {/* Kartu insight bulan puncak */}
                {(() => {
                    const s = CARD_STYLES.Insight;
                    const Icon = s.Icon;
                    return (
                        <div
                            className={`relative rounded-[2rem] pt-7 pb-9 px-6 border flex flex-col items-center text-center transition-all duration-300 shadow-sm hover:shadow-xl hover:-translate-y-0.5 overflow-hidden group ${isDark ? s.dark : s.light}`}
                        >
                            <div className={`absolute -right-10 -top-10 w-36 h-36 rounded-full border-[16px] pointer-events-none ${isDark ? s.ringDark : s.ringLight}`} />
                            <Icon className={`absolute -left-7 -bottom-7 w-36 h-36 -rotate-12 pointer-events-none ${isDark ? s.ghostDark : s.ghostLight}`} strokeWidth={1.3} />

                            <div className="relative z-10 flex flex-col items-center w-full">
                                <div className={`w-16 h-16 mb-4 rounded-[24px] bg-gradient-to-br ${s.badge} ${s.badgeShadow} flex items-center justify-center transition-all duration-300 group-hover:scale-110 group-hover:-translate-y-1`}>
                                    <Icon className="w-8 h-8 text-white stroke-[2.2] drop-shadow-[0_2px_4px_rgba(0,0,0,0.35)]" />
                                </div>

                                {noData ? (
                                    <p className={`text-sm font-bold leading-relaxed ${isDark ? 'text-slate-200' : 'text-slate-800'}`}>
                                        Belum ada data kondisi barang untuk ditampilkan.
                                    </p>
                                ) : (
                                    <>
                                        <div className={`text-2xl font-black tracking-tight ${s.value}`}>{activeData.fullMonth || activeData.name}</div>
                                        <p className={`text-sm font-bold leading-relaxed mt-1.5 ${isDark ? 'text-slate-200' : 'text-slate-800'}`}>
                                            Lonjakan signifikan terjadi pada bulan {activeData.fullMonth || activeData.name}.
                                        </p>
                                        <span className={`mt-3 inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-bold ${isDark ? s.chipDark : s.chipLight}`}>
                                            Dominan: {dominant.key} {fmtNum(activeData[dominant.pct])}%
                                        </span>
                                        {hasUnits && (
                                            <span className="mt-1.5 text-[11px] font-medium text-slate-400">{fmtNum(monthUnits, 0)} Unit tercatat</span>
                                        )}
                                    </>
                                )}
                            </div>

                            <button
                                type="button"
                                aria-label="Lihat detail insight bulan"
                                className={`absolute bottom-0 right-0 w-11 h-11 bg-gradient-to-br ${s.corner} rounded-tl-2xl rounded-br-[2rem] flex items-center justify-center cursor-pointer shadow-[inset_0_2px_3px_rgba(255,255,255,0.6),inset_0_-2px_4px_rgba(0,0,0,0.25)] transition-transform hover:scale-105 active:scale-95`}
                            >
                                <ChevronRight className="w-5 h-5 text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.3)]" />
                            </button>
                        </div>
                    );
                })()}
            </div>
        </div>
    );
}

